$(function () {
  const STORAGE_KEY = 'metrifiquese_sidebar_collapsed';

  function applySidebarState() {
    const width = window.innerWidth > 0 ? window.innerWidth : this.screen.width;
    const isCollapsedSaved = localStorage.getItem(STORAGE_KEY) === 'true';

    if (width < 1199) {
      $("#main-wrapper").attr("data-sidebartype", "mini-sidebar").addClass("mini-sidebar");
    } else {
      if (isCollapsedSaved) {
        $("#main-wrapper").attr("data-sidebartype", "mini-sidebar").addClass("mini-sidebar");
        updateToggleIcons(true);
      } else {
        $("#main-wrapper").attr("data-sidebartype", "full").removeClass("mini-sidebar");
        updateToggleIcons(false);
      }
    }
  }

  function updateToggleIcons(isMini) {
    const $toggleBtn = $("#sidebarCollapseToggle, .sidebartoggler");
    const $icon = $toggleBtn.find("i");
    if (isMini) {
      $icon.removeClass("ti-layout-sidebar-left-collapse").addClass("ti-layout-sidebar-right-collapse");
    } else {
      $icon.removeClass("ti-layout-sidebar-right-collapse").addClass("ti-layout-sidebar-left-collapse");
    }
  }

  $(window).ready(applySidebarState);
  $(window).on("resize", applySidebarState);

  $(document).on("click", ".sidebartoggler, #sidebarCollapseToggle", function (e) {
    const width = window.innerWidth > 0 ? window.innerWidth : this.screen.width;

    if (width < 1199) {
      $("#main-wrapper").toggleClass("show-sidebar");
    } else {
      $("#main-wrapper").toggleClass("mini-sidebar");
      const isMini = $("#main-wrapper").hasClass("mini-sidebar");
      
      $("#main-wrapper").attr("data-sidebartype", isMini ? "mini-sidebar" : "full");
      localStorage.setItem(STORAGE_KEY, isMini ? 'true' : 'false');
      updateToggleIcons(isMini);
    }
  });
});